import { useState } from "react";
import "./components/dropDown.css";
const VolcanesDropDown = ({ volcanes, volcanSelect, setVolcanSelect, setVolcanes }) => {
  const [isOpen, setIsOpen] = useState(false);

  const handleSelection = (volcan) => {
    if (!volcan) {
      setPlacaSeleccionada(null);
      setVolcanes(volcanes); // Restaurar todas
    } else {
      const volcanid = volcan.id.toString();
      setVolcanSelect(volcanid);
      setVolcanes([volcan]); // Solo la seleccionada
    }
    setIsOpen(false); // Cerrar el dropdown
  };

  return (
    <div className="dropdown-container">
        <h4 className="dropdown-title">Volcanes</h4>
      <button 
        className="dropdown-toggle"
        onClick={() => setIsOpen(!isOpen)}
        aria-haspopup="listbox"
        aria-expanded={isOpen}
      >
        {volcanSelect 
          ? volcanes.find(v => v.id.toString() === volcanSelect)?.descripcion 
          : "Seleccionar placa"}
        <span className={`dropdown-arrow ${isOpen ? 'open' : ''}`}>▼</span>
      </button>

      {isOpen && (
        <ul className="dropdown-menu" role="listbox">
          <li
            className={`dropdown-item ${!volcanSelect ? 'active' : ''}`}
            onClick={() => handleSelection(null)}
            role="option"
            aria-selected={!volcanSelect}
          >
            Todas los volcanes
          </li>
          {volcanes.map((volcan) => (
            <li
              key={volcan.id}
              className={`dropdown-item ${
                volcanSelect === volcan.id.toString() ? 'active' : ''
              }`}
              onClick={() => handleSelection(volcan)}
              role="option"
              aria-selected={volcanSelect === volcan.id.toString()}
            >
              {volcan.descripcion}
              {volcanSelect === volcan.id.toString() && (
                <span className="selected-icon">✓</span>
              )}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};
// Agrega esta línea al final del archivo:
export default VolcanesDropDown;
